python3 -c "
import pandas as pd,numpy as np
d=pd.read_csv('responses.csv')
sets=d.number_set.unique()
P=set([n for n in range(2,101) if all(n%a for a in range(2,int(n**.5)+1))])
pw=set([2,4,8,16,32,64]);sq=set(i*i for i in range(1,11))
for s in sets:
  e=[int(x) for x in s.split(',')]
  if len(e)<2: continue
  tags=[]
  if all(x in P for x in e): tags.append('prime')
  if all(x in pw for x in e): tags.append('pow2')
  if all(x in sq for x in e): tags.append('sq')
  for m in [3,4,6,7,8,9,11,12]:
    if all(x%m==0 for x in e): tags.append(f'm{m}')
  if tags: print(s,tags,(d.number_set==s).sum())
"

